 * > minCost(vector<vector<int>>{{1, 2, 3}, {4, 8, 2}, {1, 5, 3}}, 2, 2)
 * 8
 * > minCost(vector<vector<int>>{{2, 3, 4}, {5, 9, 3}, {2, 6, 4}}, 2, 2)
 * 12
 * > minCost(vector<vector<int>>{{3, 4, 5}, {6, 10, 4}, {3, 7, 5}}, 2, 2)
 * 16
 */
int minCost(vector<vector<int>> cost, int m, int n) {

code:
#include <bits/stdc++.h>
using namespace std;

int minCost(vector<vector<int>> cost, int m, int n) {
    int rows = cost.size();
    int cols = cost[0].size();
    vector<vector<int>> dp(rows, vector<int>(cols, INT_MAX));

    dp[0][0] = cost[0][0];
    for (int i = 0; i <= m; i++) {
        for (int j = 0; j <= n; j++) {
            if (i > 0)
                dp[i][j] = min(dp[i][j], dp[i - 1][j] + cost[i][j]);
            if (j > 0)
                dp[i][j] = min(dp[i][j], dp[i][j - 1] + cost[i][j]);
            if (i > 0 && j > 0)
                dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + cost[i][j]);
        }
    }

    return dp[m][n];
}

