    int dp[m+1][n+1][o+1];

    for (int i = 0; i <= m; i++) {
        for (int j = 0; j <= n; j++) {
            for (int k = 0; k <= o; k++) {
                if (i == 0 || j == 0 || k == 0) {
                    dp[i][j][k] = 0;
                } else if (x[i-1] == y[j-1] && y[j-1] == z[k-1]) {
